// Vectorized-load version: each warp reduces 128 consecutive columns of
// one batch row. Every lane owns 4 consecutive outputs and reads them
// with one aligned 16-byte float4 load per row, plus a second aligned
// float4 (almost always an L1 hit) used to realign the row data when
// the row start is not 16-byte aligned (dim2 not a multiple of 4).
// Split-dim1 version: two warps of the same block cooperate on one
// 128-column chunk, each reducing a strided half of the rows (row
// pairs 4k+2*sub and 4k+2*sub+1). Their partial minima are combined
// through shared memory. This halves the per-warp reduction latency
// and doubles the number of resident blocks, smoothing the tail
// imbalance that limited achieved occupancy on long dim1 reductions.
__global__ void __launch_bounds__(64) min_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int dim1, int dim2,
                                       long long total,
                                       unsigned int* __restrict__ workCounter) {
    __shared__ float4 red[2][32];
    __shared__ long long chunkBase;
    const int lane = threadIdx.x & 31;
    const int sub = threadIdx.x >> 5;
    const long long batch = total / dim2;
    const int chunksPerBatch = (dim2 + 127) >> 7;
    const long long numChunks = batch * (long long)chunksPerBatch;
    const long long totalFloats = total * (long long)dim1;
    const float inf = __int_as_float(0x7f800000);
    // Finer-grained persistent work stealing: each 64-thread block owns one
    // warp pair and atomically grabs exactly one 128-column chunk per loop.
    // This removes the old 4-chunk block group and block-wide coupling between
    // independent warp pairs, reducing the SM/SMSP active-cycle imbalance while
    // keeping the same streaming float4 reduction and split-dim1 cooperation.
    for (;;) {
        if (threadIdx.x == 0) {
            chunkBase = (long long)atomicAdd(workCounter, 1u);
        }
        __syncthreads();
        const long long w = chunkBase;
        if (w >= numChunks) break;
        const long long b = w / chunksPerBatch;
        const int d0 = (int)(w - b * (long long)chunksPerBatch) << 7;
        const long long rowBase = b * (long long)dim1 * dim2;
        int valid = dim2 - d0;
        if (valid > 128) valid = 128;
