        float4 m1 = make_float4(inf, inf, inf, inf);
        const float* s = x + rowBase + d0 + (long long)(2 * sub) * dim2;
        const bool allSafe =
            (rowBase + (long long)(dim1 - 1) * dim2 + d0 + 132) <= totalFloats;
