            int i = 2 * sub;
            for (; i + 2 <= dim1; i += 4, s += step4) {
                const float* s1 = s + dim2;
                const int off0 = (int)(((size_t)s) >> 2) & 3;
                const int off1 = (int)(((size_t)s1) >> 2) & 3;
                const float4* a40 = (const float4*)(s - off0);
                const float4* a41 = (const float4*)(s1 - off1);
                const float4 cur0 = __ldcs(a40 + lane);
                const float4 nxt0 = __ldcs(a40 + lane + 1);
                const float4 cur1 = __ldcs(a41 + lane);
                const float4 nxt1 = __ldcs(a41 + lane + 1);
                float4 r0, r1;
