                    case 0:  r0 = cur0; break;
                    case 1:  r0 = make_float4(cur0.y, cur0.z, cur0.w, nxt0.x); break;
                    case 2:  r0 = make_float4(cur0.z, cur0.w, nxt0.x, nxt0.y); break;
                    default: r0 = make_float4(cur0.w, nxt0.x, nxt0.y, nxt0.z); break;
                }
                switch (off1) {
                    case 0:  r1 = cur1; break;
                    case 1:  r1 = make_float4(cur1.y, cur1.z, cur1.w, nxt1.x); break;
                    case 2:  r1 = make_float4(cur1.z, cur1.w, nxt1.x, nxt1.y); break;
                    default: r1 = make_float4(cur1.w, nxt1.x, nxt1.y, nxt1.z); break;
                }
