                        m0.y = fminf(m0.y, r.y);
                        m0.z = fminf(m0.z, r.z);
                        m0.w = fminf(m0.w, r.w);
                    } else {
                        #pragma unroll
                        for (int j = 0; j < 4; ++j) {
                            const int dd = 4 * lane + j;
                            if (dd < valid) {
                                const float v = __ldcs(sr + dd);
                                if (j == 0)      m0.x = fminf(m0.x, v);
                                else if (j == 1) m0.y = fminf(m0.y, v);
                                else if (j == 2) m0.z = fminf(m0.z, v);
                                else             m0.w = fminf(m0.w, v);
                            }
                        }
                    }
                }
            }
        }
        m0.x = fminf(m0.x, m1.x);
        m0.y = fminf(m0.y, m1.y);
        m0.z = fminf(m0.z, m1.z);
        m0.w = fminf(m0.w, m1.w);
        red[sub][lane] = m0;
        __syncthreads();
        if (sub == 0) {
            const float4 o = red[1][lane];
            m0.x = fminf(m0.x, o.x);
            m0.y = fminf(m0.y, o.y);
            m0.z = fminf(m0.z, o.z);
            m0.w = fminf(m0.w, o.w);
            float* ob = out + b * (long long)dim2 + d0;
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                const int dd = 4 * lane + j;
                if (dd < valid) {
                    ob[dd] = (j == 0) ? m0.x : (j == 1) ? m0.y : (j == 2) ? m0.z : m0.w;
                }
            }
        }
        __syncthreads();
    }
}

