    long long chunksPerBatch = (dim2 + 127) / 128;
    long long numChunks = batch * chunksPerBatch;
    // Persistent one-wave grid, but with chunk-granular stealing by each
    // independent 64-thread warp-pair block instead of 4-chunk 256-thread groups.
    static int blocksPerWave = 0;
