    if (d_workCounter == nullptr) {
        cudaMalloc(&d_workCounter, sizeof(unsigned int));
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cudaMemsetAsync(d_workCounter, 0, sizeof(unsigned int), stream);
    min_reduce_dim1_kernel<<<(int)blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(),
        (int)dim1, (int)dim2, total, d_workCounter);
    return out;
